SourceCode.Declaration:
/// <summary>
/// Every posting the handheld has made, keyed by the idempotency key it sent.
///
/// **This table is what stops a receipt being posted twice.** A handheld on warehouse wifi loses
/// responses regularly: the posting commits, the reply never arrives, and the queue retries. With
/// nothing to recognise the replay, the second attempt posts a second product receipt and the
/// stock is booked in twice — a discrepancy that surfaces weeks later at a count, by which time
/// nobody can explain it.
///
/// So the client mints a key per captured transaction and sends it with every attempt. The first
/// attempt writes a row here inside the same transaction as the posting itself; a replay finds the
/// row and returns the original document number without posting anything. The unique index is what
/// enforces that under concurrency — two devices, or two retries racing, cannot both insert.
///
/// The row is the receipt of record for the device, so it is never cleaned up automatically. It is
/// small, and the day it matters is the day someone is asking why a pallet was counted twice.
/// </summary>
public class HSMobileOpsPostLog extends common
{
}

Method.Source:
/// <summary>
/// The posting already made under this idempotency key, if any.
/// </summary>
public static HSMobileOpsPostLog findByKey(str _idempotencyKey, boolean _forUpdate = false)
{
    HSMobileOpsPostLog postLog;

    if (!_idempotencyKey)
    {
        return postLog;
    }

    postLog.selectForUpdate(_forUpdate);

    select firstOnly postLog
        where postLog.IdempotencyKey == _idempotencyKey;

    return postLog;
}
